<?php
require_once '../includes/auth.php';requireActiveUser();requireTenantContext();requireModulePermission('operations','view');
global $conn;$tenantId=(int)getCurrentTenantId();$rows=[];$q=$conn->prepare("SELECT * FROM adverts WHERE tenant_id=? ORDER BY id DESC LIMIT 200");if($q){$q->bind_param('i',$tenantId);$q->execute();$z=$q->get_result();while($r=$z->fetch_assoc())$rows[]=$r;$q->close();}
$pageTitle='Adverts & Announcements';require_once '../includes/header.php';?><div class="dashboard-card"><div class="page-header"><div><h2>Adverts &amp; Announcements</h2><p>Manage customer-facing campaigns, notices and promotional messages.</p></div></div><?php foreach($rows as $x):?><div class="card" style="padding:16px;margin:10px 0"><strong><?=e($x['title'])?></strong><span style="margin-left:10px"><?=e($x['status'])?></span><p><?=nl2br(e($x['message']))?></p></div><?php endforeach;?><?php if(!$rows):?><p>No adverts or announcements yet.</p><?php endif;?></div><?php require_once '../includes/footer.php';?>